export const Rating: FC<RatingProps> = ({
  value,
  maxStars = 5,
  size,
  onChange,
  readOnly = true,
  showScore = false,
  className,
  ariaLabel,
  variant = 'star',
}) => {
  const [hoverValue, setHoverValue] = useState<number | null>(null);
  const activeRating = hoverValue !== null ? hoverValue : value;

  const isPaw = variant === 'paw';
  const effectiveSize = size ?? (isPaw ? 28 : 20);
  const pathD = isPaw ? PAW_PATH : STAR_PATH;
  const viewBox = isPaw ? '0 0 24 24' : '0 0 20 20';
  const inactiveColor = isPaw ? '#96B3E2' : 'var(--color-interactive-lightgray)';
  const activeColor = 'var(--color-interactive-primary)';

  return (
    <div
      className={['ui-rating inline-flex items-center gap-1.5', className].filter(Boolean).join(' ')}
      role={readOnly ? 'img' : 'radiogroup'}
      aria-label={ariaLabel || `Оцінка: ${value} з ${maxStars}`}
    >
      <div className={['ui-rating__stars inline-flex', isPaw ? 'gap-3' : 'gap-1'].join(' ')}>
        {Array.from({ length: maxStars }).map((_, index) => {
          const starIndex = index + 1;
          const isFilled = starIndex <= activeRating;
          const fillColor = isFilled ? activeColor : inactiveColor;

          if (readOnly) {
            return (
              <svg
                key={starIndex}
                width={effectiveSize}
                height={effectiveSize}
                viewBox={viewBox}
                fill="none"
                aria-hidden="true"
                className="ui-rating__star shrink-0"
              >
                <path d={pathD} fill={fillColor} />
              </svg>
            );
          }

          return (
            <button
              key={starIndex}
              type="button"
              role="radio"
              aria-checked={value === starIndex}
              aria-label={`Оцінити ${starIndex} ${isPaw ? 'лапок' : 'зірок'}`}
              onMouseEnter={() => setHoverValue(starIndex)}
              onMouseLeave={() => setHoverValue(null)}
              onClick={() => onChange?.(starIndex)}
              className="bg-transparent border-0 p-0 cursor-pointer transition-transform hover:scale-110 outline-none flex items-center justify-center"
            >
              <svg
                width={effectiveSize}
                height={effectiveSize}
                viewBox={viewBox}
                fill="none"
                aria-hidden="true"
                className="shrink-0"
              >
                <path d={pathD} fill={fillColor} />
              </svg>
            </button>
          );
        })}
      </div>
      {showScore && (
        <span className="ui-rating__score text-sm font-accented font-semibold text-content-dark">
          {value.toFixed(1)}
        </span>
      )}
    </div>
  );
};

export default Rating;
